Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello over a socket`n")
[IO.File]::WriteAllText((Join-Path $PWD 'taken.sock'), "not a socket`n")
[IO.File]::WriteAllText((Join-Path $PWD 'on-a-socket.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Serves site/ on the Unix socket file <socket>, waits until surl listens, runs <command>`n# with SURL_PID set to surl's process ID, then stops surl. Exits with the command's exit code.`n# Usage: sh on-a-socket.sh <socket> <listen URL> <command> [<argument>...]`nsocket=`$1; url=`$2; shift 2`nsurl --directory site --unix-socket `"`$socket`" `"`$url`" > surl.out &`nSURL_PID=`$!`nexport SURL_PID`n`n# surl writes `"Listening on`" once the socket file is bound. If it exits first, it refused`n# to start: pass its exit code on.`ntries=0`nuntil grep -q '^Listening on ' surl.out 2>/dev/null; do`n  if ! kill -0 `"`$SURL_PID`" 2>/dev/null; then wait `"`$SURL_PID`"; exit; fi`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 300 ]; then echo `"surl wrote no Listening on line`" >&2; exit 1; fi`n  sleep 0.1`ndone`ncat surl.out`n`n`"`$@`"`nstatus=`$?`nkill `"`$SURL_PID`" 2>/dev/null`nwait `"`$SURL_PID`"`nexit `"`$status`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'kill-it.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Stands in for a crash: kills the surl that on-a-socket.sh started, outright, and waits`n# until it is gone.`nkill -9 `"`$SURL_PID`"`nwhile kill -0 `"`$SURL_PID`" 2>/dev/null; do sleep 0.1; done`n")
sh on-a-socket.sh surl.sock http://localhost:8080/ curl -s --unix-socket surl.sock http://localhost:8080/hello.txt
